pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // The reference C's oracle is a contract during initialization; we can call atVersion
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("atVersion(uint256)", version));
        if (success) {
            // If the call succeeds, the oracle address must not be zero
            // However, we cannot directly read the oracle because the getter is view but returns an interface
            // We can check by reading the oracle address directly via the getter
            (bool oracleSuccess, bytes memory oracleData) = address(c).staticcall(abi.encodeWithSignature("oracle()"));
            if (oracleSuccess) {
                address oracleAddr = abi.decode(oracleData, (address));
                assertTrue(oracleAddr != address(0), "Oracle must not be zero address");
            }
        }
    }
}

