        // Bound oracleVersion to avoid unrealistic values (but still fuzzed)
        vm.assume(oracleVersion <= 1000000);

        // Call atVersion which internally uses oracle()
        // The call should succeed (not revert) because the reference oracle is a contract
        (bool success, bytes memory data) = address(c).staticcall(
            abi.encodeWithSelector(c.atVersion.selector, oracleVersion)
        );

        // The rule: the call must succeed (not revert) when oracle is a valid contract
        // In the buggy version, oracle() returns address(0), causing atVersion to fail
