import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 version) public {
        vm.assume(version > 0);

        // Get current version and a historical version
        (bool success1, bytes memory data1) = address(c).staticcall(abi.encodeWithSignature("atVersion(uint256)", version));
        (bool success2, bytes memory data2) = address(c).staticcall(abi.encodeWithSignature("currentVersion()"));

        // Both calls must succeed
        assertTrue(success1);
        assertTrue(success2);

        // Decode the prices from both calls
        // atVersion returns OracleVersion which has version, timestamp, price
        (uint256 v1, uint256 ts1, int256 price1) = abi.decode(data1, (uint256, uint256, int256));
        (uint256 v2, uint256 ts2, int256 price2) = abi.decode(data2, (uint256, uint256, int256));

        // The rule: atVersion(version) should return historical data, not current data
        // We can't directly check the oracle, but we know atVersion should differ from currentVersion
        // unless version happens to be the current version exactly
        // So we assert that either the versions differ (different oracle version), or
        // if same version, the prices must match (which is correct behavior)

        if (v1 == v2) {
            // If same version, prices should match (reference behavior)
            assertTrue(price1 == price2);
        } else {
            // Different versions should have different timestamps (oracle version timestamps differ)
            // But if the bug is that atVersion returns currentVersion, then v1 would equal v2
            // So the assertion is: v1 should be != v2 for non-zero version
            assertTrue(v1 != v2);
        }
    }
}

