pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // Restrict oracleVersion to a valid range (avoid zero or reverts)
        vm.assume(oracleVersion > 0 && oracleVersion < 100);

        // Get the current oracle version from the product's oracle
        (bool successCurrent, bytes memory dataCurrent) = address(c.oracle()).staticcall(
            abi.encodeWithSignature("currentVersion()")
        );
        require(successCurrent, "currentVersion failed");

        // Decode the current oracle version
        (uint256 currentVersionNum, uint256 currentTimestamp, int256 currentPrice) = abi.decode(dataCurrent, (uint256, uint256, int256));

        // Get the oracle version at the given oracleVersion parameter
        (bool successAt, bytes memory dataAt) = address(c.oracle()).staticcall(
            abi.encodeWithSignature("atVersion(uint256)", oracleVersion)
        );
        require(successAt, "atVersion failed");

        // Decode the oracle version at the requested parameter
        (uint256 versionNum, uint256 timestamp, int256 price) = abi.decode(dataAt, (uint256, uint256, int256));

        // Get the product's atVersion result
        (bool successProduct, bytes memory dataProduct) = address(c).staticcall(
            abi.encodeWithSignature("atVersion(uint256)", oracleVersion)
        );
        require(successProduct, "product atVersion failed");

        // Decode the product's result
        (uint256 prodVersion, uint256 prodTimestamp, int256 prodPrice) = abi.decode(dataProduct, (uint256, uint256, int256));

        // The prodPrice should equal the transformed price from oracle().atVersion(version), not the current price
        // The transformation is defined in PayoffDefinitionLib.transform, but we can assert that
        // prodPrice is the result of transforming the oracle price at that version, not the current price.
        // As a general rule, if the requested oracleVersion is different from the current version,
        // then the product's atVersion should return a price different from the current version's price.
        if (oracleVersion != currentVersionNum) {
            assertTrue(prodPrice != currentPrice, "atVersion should not return current price when version differs");
        }
        // Additionally, the product version should match the requested oracle version
        assertTrue(prodVersion == oracleVersion, "Product atVersion should return the requested version");
    }
}

