        info.oracle = IOracleProvider(dummyOracle);
        // Now set payoffDefinition to something valid.
        info.payoffDefinition.payoffType = PayoffDefinitionLib.PayoffType.LINEAR;
        info.payoffDefinition.payoffDirection = PayoffDefinitionLib.PayoffDirection.LONG;
        // Initialize
        c.initialize(info);
        // Now makerFee should be exactly the set makerFee.
        uint256 returnedMakerFee = UFixed18.unwrap(c.makerFee());
        assertTrue(returnedMakerFee == makerFee, "makerFee differs");
    }
}

